#include "ImageQueue.h"
namespace drawborad {
Result<QueueId> ImageQueue::enqueue(std::span<const std::filesystem::path> paths,const QueuePolicy&p){if(paths.empty())return error(ErrorCode::InvalidInput,"queue.empty");if(id_.empty())id_=Id::fromNumber(0x5155455545ull);policy_=p;for(const auto&path:paths){if(path.empty())return error(ErrorCode::InvalidInput,"queue.path");QueueItem q;q.id=Id::fromNumber(items_.size()+1);q.input=path;items_.push_back(std::move(q));}return id_;}
void ImageQueue::pause(QueueId id){if(id==id_)paused_=true;}
Result<void> ImageQueue::resume(QueueId id){if(id!=id_)return error(ErrorCode::InvalidInput,"queue.id");paused_=false;return{};}
Result<void> ImageQueue::startAnalysis(std::size_t i){if(paused_)return error(ErrorCode::Locked,"queue.paused");if(i>=items_.size()||items_[i].state!=QueueState::Queued)return error(ErrorCode::InvalidInput,"queue.state");if(activeHeavy_)return error(ErrorCode::BudgetExceeded,"queue.single-heavy");activeHeavy_=i;items_[i].state=QueueState::Analyzing;return{};}
Result<void> ImageQueue::analysisComplete(std::size_t i,bool hasReview){if(!activeHeavy_||*activeHeavy_!=i||items_[i].state!=QueueState::Analyzing)return error(ErrorCode::InvalidInput,"queue.state");activeHeavy_.reset();items_[i].state=(hasReview&&!policy_.autoAcceptReview)?QueueState::WaitingForReview:QueueState::Reconstructing;if(items_[i].state==QueueState::Reconstructing){if(activeHeavy_)return error(ErrorCode::BudgetExceeded,"queue.single-heavy");activeHeavy_=i;}return{};}
Result<void> ImageQueue::acceptReview(std::size_t i,Revision current){if(i>=items_.size()||items_[i].state!=QueueState::WaitingForReview)return error(ErrorCode::InvalidInput,"queue.state");items_[i].inputRevision=current;if(activeHeavy_)return error(ErrorCode::BudgetExceeded,"queue.single-heavy");items_[i].state=QueueState::Reconstructing;activeHeavy_=i;return{};}
Result<void> ImageQueue::finish(std::size_t i,bool success,std::string e){if(i>=items_.size())return error(ErrorCode::InvalidInput,"queue.item");auto state=items_[i].state;if(state!=QueueState::Analyzing&&state!=QueueState::Reconstructing)return error(ErrorCode::InvalidInput,"queue.state");if(success&&state!=QueueState::Reconstructing)return error(ErrorCode::InvalidInput,"queue.success-before-reconstruct");if(activeHeavy_&&*activeHeavy_==i)activeHeavy_.reset();items_[i].state=success?QueueState::Done:QueueState::Failed;items_[i].error=std::move(e);return{};}
Result<void> ImageQueue::cancel(std::size_t i){if(i>=items_.size())return error(ErrorCode::InvalidInput,"queue.item");if(activeHeavy_&&*activeHeavy_==i)activeHeavy_.reset();items_[i].state=QueueState::Cancelled;return{};}
}
